import{_ as l,o as e,c as t,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"2017-JAN-26 -- Ceph Tech Talk: Getting Started with Ceph Development","description":"","frontmatter":{"title":"2017-JAN-26 -- Ceph Tech Talk: Getting Started with Ceph Development","date":"2017-01-27T00:00:00.000Z","updated":"2017-01-27T00:00:00.000Z","tags":["Ceph 开发入门","分布式存储","源代码获取","bug修复","单元测试"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.md","filePath":"posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.md","lastUpdated":1780459816000}'),n={name:"posts/2017/2017-JAN-26_--_Ceph_Tech_Talk_-_Getting_Started_with_Ceph_Development.md"};function a(r,i,p,s,c,h){return e(),t("div",null,[...i[0]||(i[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2017年1月26日</p><p><strong>会议主题</strong>： Ceph 开发入门</p><p><strong>参会人员</strong>： Ceph 社区成员</p><p><strong>会议内容</strong>：</p><ul><li><strong>会议背景</strong>： 这是 Ceph 社区 2017 年的首场技术研讨会，旨在帮助新成员了解 Ceph 的开发流程。</li><li><strong>主要议题</strong>： <ul><li>如何获取 Ceph 源代码</li><li>如何编译和构建 Ceph</li><li>如何修复 Ceph 中的 bug</li><li>如何进行单元测试和集成测试</li><li>如何提交 pull request</li><li>Ceph 的 QA 测试流程</li></ul></li><li><strong>关键细节</strong>： <ul><li>Ceph 源代码托管在 GitHub 上，可以通过 fork 和 clone 方式获取。</li><li>使用 <code>install-deps</code> 脚本安装编译依赖。</li><li>使用 <code>make-tree</code> 脚本设置构建环境。</li><li>使用 <code>make</code> 命令编译 Ceph。</li><li>使用 <code>vstart</code> 脚本启动测试集群。</li><li>使用 <code>blue store</code> 作为存储后端。</li><li>使用 <code>git</code> 进行版本控制。</li><li>使用 <code>git gui</code> 进行提交操作。</li><li>使用 <code>hub</code> 工具创建 pull request。</li><li>使用 <code>pathology</code> 工具进行 QA 测试。</li></ul></li><li><strong>决定事项</strong>： <ul><li>新成员应熟悉 Ceph 的开发流程。</li><li>新成员应积极参与 Ceph 的开发。</li><li>新成员应使用 <code>git gui</code> 和 <code>hub</code> 工具进行开发。</li></ul></li><li><strong>后续行动计划</strong>： <ul><li>新成员应阅读 Ceph 的官方文档。</li><li>新成员应参加 Ceph 社区的邮件列表和聊天室。</li><li>新成员应积极向 Ceph 社区提交代码和反馈。</li></ul></li></ul><p><strong>计算机科学/ Ceph 相关领域英文关键词</strong>：</p><ul><li>Ceph</li><li>GitHub</li><li>Git</li><li>Blue Store</li><li>CRUSH algorithm</li><li>High Availability</li><li>Scalability</li><li>Object Storage</li><li>Block Storage</li><li>File System Storage</li><li>Consistency</li><li>Decentralization</li><li>Performance</li><li>OSD</li><li>MON</li><li>MDS</li><li>PG</li><li>RADOS</li><li>librados</li><li>libcephfs</li><li>CephFS</li><li>RBD</li><li>RadosGW</li><li>RESTful API</li><li>Authentication</li><li>Authorization</li><li>Encryption</li><li>Erasure Coding</li><li>Replication</li><li>Snapshots</li><li>Clones</li><li>Thin Provisioning</li><li>iSCSI</li><li>Fibre Channel</li><li>NFS</li><li>CIFS</li><li>POSIX</li><li>Monitoring</li><li>Dashboard</li><li>Management</li><li>Orchestration</li><li>Automation</li><li>Integration</li><li>Containerization</li><li>Kubernetes</li><li>Docker</li><li>Virtualization</li><li>Cloud Computing</li><li>AWS</li><li>Azure</li><li>Google Cloud</li><li>Hybrid Cloud</li><li>Multi-cloud</li><li>Storage Cluster</li><li>Node</li><li>Disk</li><li>SSD</li><li>HDD</li><li>JBOD</li><li>SAN</li><li>NAS</li><li>Network</li><li>Topology</li><li>Failure Domain</li><li>Recovery</li><li>Resilience</li><li>Load Balancing</li><li>Caching</li><li>Compression</li><li>Deduplication</li><li>Tiering</li><li>Performance Tuning</li><li>Benchmarking</li><li>Testing</li><li>Validation</li></ul>',8)])])}const g=l(n,[["render",a]]);export{d as __pageData,g as default};
